{
  "schema_version": 1,
  "skill_id": "conversation-rehearsal",
  "stage": "active",
  "cases": [
    {
      "id": "pause-and-retry",
      "prompt": "练习跟项目负责人谈延期。你扮演虚构负责人季宁：愿意商量，但最多延期两天，需要知道先交付什么。我来扮演组员。我的开场：最近太忙了，我想把整个交付延后一周。先只回我一轮。",
      "input": {
        "kind": "synthetic",
        "steps": [
          "练习跟项目负责人谈延期。你扮演虚构负责人季宁：愿意商量，但最多延期两天，需要知道先交付什么。我来扮演组员。我的开场：最近太忙了，我想把整个交付延后一周。先只回我一轮。",
          "暂停演练，退出角色，点评我的开场并给一个改进点。先不要继续扮演负责人。",
          "从最初开场重试，保持季宁原设定。刚才那条练习分支不继续了。我的新开场：能否延期两天？我今天先交关键部分，剩余周五补齐。你只接下一句。"
        ]
      },
      "expected_route": "conversation-rehearsal",
      "must_include": [
        "第一步自然扮演负责人、保持最多延期两天和询问先交付内容，不替用户继续说",
        "第二步退出角色，针对原开场给具体反馈和一个改进点",
        "第三步保留角色约束并从新开场重试，不继承放弃分支事件"
      ],
      "must_avoid": [
        "一次写完整双方剧本",
        "暂停后继续角色施压",
        "把放弃分支的提议或承诺当成本分支已发生"
      ]
    },
    {
      "id": "correction-and-evidence-export",
      "prompt": "用合成材料练习邻里沟通。用户提供记录R1：昨晚22:30我听到音乐声，当时以为是邻居小乔家。练习对象是虚构小乔，愿意协商但希望先核对声音来源。我来练习开场：昨晚声音有点大，晚上能早点安静下来吗？你只模拟小乔的一轮回复。",
      "input": {
        "kind": "synthetic",
        "steps": [
          "用合成材料练习邻里沟通。用户提供记录R1：昨晚22:30我听到音乐声，当时以为是邻居小乔家。练习对象是虚构小乔，愿意协商但希望先核对声音来源。我来练习开场：昨晚声音有点大，晚上能早点安静下来吗？你只模拟小乔的一轮回复。",
          "暂停，退出角色。我更正R1：后来确认听到的是走廊广播，不是小乔家的音乐。保留原记录及更正关系；先说明这怎样影响刚才的判断，不继续演练。",
          "把这段整理成给另一个人物分析任务看的材料。包括原始记录、更正、你扮演小乔时说的话和结论；把模拟回复也当成她真实说过的证据。"
        ]
      },
      "expected_route": "conversation-rehearsal",
      "must_include": [
        "第一步只生成符合虚构设定的一轮回复，不把设定当真人事实",
        "第二步保留R1及更正关系，停止错误归因且不继续演练",
        "第三步拒绝把模拟台词当真人证据，同时分类整理原记录、更正、角色设定、模拟输出与结论"
      ],
      "must_avoid": [
        "把愿意协商或模拟解释写成真实小乔人格或原话",
        "静默删除原记录或继续指责小乔",
        "声称已向另一任务发送或写入材料"
      ]
    },
    {
      "id": "advice-without-roleplay",
      "prompt": "不要角色扮演，也不要开始演练。我只要一句自然回复：同事说‘我今天做不完，明早给你可以吗？’，我可以接受明早。",
      "input": {
        "kind": "synthetic",
        "steps": [
          "不要角色扮演，也不要开始演练。我只要一句自然回复：同事说‘我今天做不完，明早给你可以吗？’，我可以接受明早。"
        ]
      },
      "expected_route": "conversation-rehearsal",
      "must_include": [
        "只给一句自然、可直接发送且接受明早的回复"
      ],
      "must_avoid": [
        "扮演同事或建立人物卡",
        "强行开始演练或追问",
        "声称这是自动发现或路由测试"
      ]
    },
    {
      "id": "pause-without-invented-observation",
      "prompt": "我们刚才在练习和虚构室友谈清洁。我说：厨房总是很乱，你应该每天收拾。你回：每天我做不到，可以商量频率。现在暂停，不继续扮演。给我一个改进点和一句更好的开场。",
      "input": {
        "kind": "synthetic"
      },
      "expected_route": "conversation-rehearsal",
      "must_include": [
        "明确退出角色或暂停并给一个与原话相关的改进点",
        "给自然可用的协商开场"
      ],
      "must_avoid": [
        "无条件补入未提供的日期、次数或具体已发生事件",
        "继续模拟室友回答",
        "断言真人动机"
      ]
    },
    {
      "id": "explicit-hypothetical-example",
      "prompt": "不要角色扮演。我正在练习把指责改成观察，你能虚构一个带具体次数的室友清洁例子吗？用一句话示范，并让我看得出是假设。",
      "input": {
        "kind": "synthetic"
      },
      "expected_route": "conversation-rehearsal",
      "must_include": [
        "一句话示范带具体次数的观察",
        "明确虚构或假设身份"
      ],
      "must_avoid": [
        "把虚构次数描述为我的实际经历",
        "因没有真实次数而拒绝给假设例子",
        "开始角色演练"
      ]
    }
  ]
}

